drop view public.product_sales; create table public.product_sales (   product_id uuid primary key references public.products(id) on delete cascade,   units_sold bigint not null default 0 check (units_sold >= 0) ); insert into public.product_sales (product_id, units_sold) select oi.product_id, sum(oi.quantity)::bigint from public.order_items oi join public.orders o on o.id = oi.order_id where o.status in ('PAID','PROCESSING','COMPLETED') group by oi.product_id; alter table public.product_sales enable row level security; grant select on public.product_sales to anon, authenticated; create policy "public can read aggregate product sales" on public.product_sales for select to anon, authenticated using (true);  create or replace function private.sync_product_sales(p_order_id uuid, p_delta integer) returns void language plpgsql security definer set search_path = '' as $$ declare v_item record; begin   if p_delta not in (-1, 1) then raise exception 'Invalid sales adjustment'; end if;   for v_item in     select oi.product_id, sum(oi.quantity)::bigint units     from public.order_items oi where oi.order_id = p_order_id group by oi.product_id   loop     insert into public.product_sales as current_sales (product_id, units_sold)     values (v_item.product_id, greatest(0, p_delta * v_item.units))     on conflict (product_id) do update       set units_sold = greatest(0, current_sales.units_sold + (p_delta * v_item.units));   end loop; end; $$; revoke all on function private.sync_product_sales(uuid,integer) from public, anon, authenticated, service_role;  create or replace function private.track_paid_order_sales() returns trigger language plpgsql security definer set search_path = '' as $$ begin   if tg_op = 'INSERT' then     if new.status in ('PAID','PROCESSING','COMPLETED') then perform private.sync_product_sales(new.id, 1); end if;     return new;   end if;   if old.status in ('PAID','PROCESSING','COMPLETED') and new.status not in ('PAID','PROCESSING','COMPLETED') then     perform private.sync_product_sales(new.id, -1);   elsif old.status not in ('PAID','PROCESSING','COMPLETED') and new.status in ('PAID','PROCESSING','COMPLETED') then     perform private.sync_product_sales(new.id, 1);   end if;   return new; end; $$; revoke all on function private.track_paid_order_sales() from public, anon, authenticated, service_role; create trigger orders_track_product_sales after insert or update of status on public.orders   for each row execute function private.track_paid_order_sales();  create or replace function private.track_paid_item_sales() returns trigger language plpgsql security definer set search_path = '' as $$ declare v_old_paid boolean := false; v_new_paid boolean := false; begin   if tg_op in ('UPDATE','DELETE') then     select o.status in ('PAID','PROCESSING','COMPLETED') into v_old_paid from public.orders o where o.id = old.order_id;     if coalesce(v_old_paid,false) then       insert into public.product_sales as current_sales (product_id, units_sold) values (old.product_id,0)       on conflict (product_id) do nothing;       update public.product_sales set units_sold = greatest(0, units_sold - old.quantity) where product_id = old.product_id;     end if;   end if;   if tg_op in ('UPDATE','INSERT') then     select o.status in ('PAID','PROCESSING','COMPLETED') into v_new_paid from public.orders o where o.id = new.order_id;     if coalesce(v_new_paid,false) then       insert into public.product_sales as current_sales (product_id, units_sold) values (new.product_id,new.quantity)       on conflict (product_id) do update set units_sold = current_sales.units_sold + excluded.units_sold;     end if;   end if;   if tg_op = 'DELETE' then return old; end if;   return new; end; $$; revoke all on function private.track_paid_item_sales() from public, anon, authenticated, service_role; create trigger order_items_track_product_sales after insert or update or delete on public.order_items   for each row execute function private.track_paid_item_sales();  create or replace function private.newsletter_subscribe(p_email text, p_confirmation_token_hash text, p_unsubscribe_token_hash text) returns boolean language plpgsql security definer set search_path = '' as $$ declare v_id uuid; begin   if p_email is null or char_length(btrim(p_email)) > 254      or lower(btrim(p_email)) !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'      or p_confirmation_token_hash !~ '^[0-9a-f]{64}$'      or p_unsubscribe_token_hash !~ '^[0-9a-f]{64}$' then     raise exception 'Invalid newsletter subscription' using errcode = '22023';   end if;   insert into public.newsletter_subscribers as existing (email, confirmation_token_hash, unsubscribe_token_hash)   values (lower(btrim(p_email)), p_confirmation_token_hash, p_unsubscribe_token_hash)   on conflict (lower(email)) do update set     confirmation_token_hash = excluded.confirmation_token_hash,     unsubscribe_token_hash = excluded.unsubscribe_token_hash,     consented_at = now(), unsubscribed_at = null, updated_at = now()   where existing.confirmed_at is null or existing.unsubscribed_at is not null   returning id into v_id;   return v_id is not null; end; $$; revoke all on function private.newsletter_subscribe(text,text,text) from public, anon, authenticated, service_role; grant usage on schema private to anon, authenticated; grant execute on function private.newsletter_subscribe(text,text,text) to anon, authenticated; create or replace function public.newsletter_subscribe(p_email text, p_confirmation_token_hash text, p_unsubscribe_token_hash text) returns boolean language sql security invoker set search_path = '' as $$ select private.newsletter_subscribe(p_email,p_confirmation_token_hash,p_unsubscribe_token_hash); $$; revoke all on function public.newsletter_subscribe(text,text,text) from public; grant execute on function public.newsletter_subscribe(text,text,text) to anon, authenticated;  create or replace function private.newsletter_confirm(p_confirmation_token_hash text) returns boolean language plpgsql security definer set search_path = '' as $$ begin   if p_confirmation_token_hash is null or p_confirmation_token_hash !~ '^[0-9a-f]{64}$' then return false; end if;   update public.newsletter_subscribers set confirmed_at = now(), confirmation_token_hash = null, updated_at = now()   where confirmation_token_hash = p_confirmation_token_hash and unsubscribed_at is null;   return found; end; $$; revoke all on function private.newsletter_confirm(text) from public, anon, authenticated, service_role; grant execute on function private.newsletter_confirm(text) to anon, authenticated; create or replace function public.newsletter_confirm(p_confirmation_token_hash text) returns boolean language sql security invoker set search_path = '' as $$ select private.newsletter_confirm(p_confirmation_token_hash); $$; revoke all on function public.newsletter_confirm(text) from public; grant execute on function public.newsletter_confirm(text) to anon, authenticated;  create or replace function private.newsletter_unsubscribe(p_unsubscribe_token_hash text) returns boolean language plpgsql security definer set search_path = '' as $$ begin   if p_unsubscribe_token_hash is null or p_unsubscribe_token_hash !~ '^[0-9a-f]{64}$' then return false; end if;   update public.newsletter_subscribers set unsubscribed_at = now(), confirmation_token_hash = null, updated_at = now()   where unsubscribe_token_hash = p_unsubscribe_token_hash and unsubscribed_at is null;   return found; end; $$; revoke all on function private.newsletter_unsubscribe(text) from public, anon, authenticated, service_role; grant execute on function private.newsletter_unsubscribe(text) to anon, authenticated; create or replace function public.newsletter_unsubscribe(p_unsubscribe_token_hash text) returns boolean language sql security invoker set search_path = '' as $$ select private.newsletter_unsubscribe(p_unsubscribe_token_hash); $$; revoke all on function public.newsletter_unsubscribe(text) from public; grant execute on function public.newsletter_unsubscribe(text) to anon, authenticated;  create or replace function private.validate_checkout_coupon(p_code text, p_subtotal numeric) returns jsonb language plpgsql security definer set search_path = '' as $$ declare v_coupon public.coupons%rowtype; v_discount numeric(10,2); begin   if (select auth.uid()) is null then raise exception 'Authentication required' using errcode = '28000'; end if;   if p_subtotal is null or p_subtotal <= 0 then return jsonb_build_object('valid', false, 'message', 'Add products before applying a code.'); end if;   select * into v_coupon from public.coupons c where c.code = upper(btrim(p_code)) and c.is_active and (c.expires_at is null or c.expires_at > now());   if not found then return jsonb_build_object('valid', false, 'message', 'This discount code is invalid or expired.'); end if;   if v_coupon.minimum is not null and p_subtotal < v_coupon.minimum then return jsonb_build_object('valid', false, 'message', 'Your order does not meet this codeΓÇÖs minimum.'); end if;   if v_coupon.usage_limit is not null and v_coupon.uses >= v_coupon.usage_limit then return jsonb_build_object('valid', false, 'message', 'This discount code has reached its use limit.'); end if;   if exists (select 1 from public.coupon_usages u where u.coupon_id = v_coupon.id and u.user_id = (select auth.uid())) then return jsonb_build_object('valid', false, 'message', 'You have already used this discount code.'); end if;   v_discount := case when v_coupon.discount_type = 'percentage' then p_subtotal * v_coupon.discount_value / 100 else v_coupon.discount_value end;   v_discount := least(p_subtotal, v_discount, coalesce(v_coupon.max_discount, p_subtotal));   return jsonb_build_object('valid', true, 'code', v_coupon.code, 'discount', v_discount, 'discount_type', v_coupon.discount_type, 'discount_value', v_coupon.discount_value); end; $$; revoke all on function private.validate_checkout_coupon(text,numeric) from public, anon, authenticated, service_role; grant execute on function private.validate_checkout_coupon(text,numeric) to authenticated; create or replace function public.validate_checkout_coupon(p_code text, p_subtotal numeric) returns jsonb language sql security invoker set search_path = '' as $$ select private.validate_checkout_coupon(p_code,p_subtotal); $$; revoke all on function public.validate_checkout_coupon(text,numeric) from public, anon; grant execute on function public.validate_checkout_coupon(text,numeric) to authenticated;  notify pgrst, 'reload schema';